@require_POST
def transcode_video_asset(request, video_id):
    video = get_object_or_404(VideoAsset, id=video_id, uploader=request.user)
    target_format = request.POST.get('format', 'mp4')
    output_prefix = f"users/{request.user.id}/transcodes/"
    transcode_media_task.delay(video.id, target_format, output_prefix)
    return JsonResponse({'status': 'transcoding started'})
